mapper.update:
update user_admin
set inside_address     = #{insideAddress},
    inside_private_key = #{insidePrivateKey}
where address = #{address}

mapper.select:
select *
from user_admin


        and `role` = #{role}


        and `child_role` = #{childRole}


        and `status` = #{status}


        and `apply_status` = #{applyStatus}


        and parent_address = #{parentAddress}


        and register_time >= #{startTime}


        and #{endTime} >= register_time


        and (
        address = #{vague}
        or parent_address = #{vague}
        or inside_address = #{vague}
        or nickname like CONCAT('%', #{vague}, '%')
        )


order by uid desc
